-- Datos de EJEMPLO para probar /destinos en una D1 LOCAL (wrangler d1 execute travel-puzzle --local --file ...).
-- NUNCA contra la base remota: son tours inventados. Ver docs/plan-primera-pieza.md (capturas de la Ola 4).
DELETE FROM "TourTranslation" WHERE "tourId" LIKE 'ej-%';
DELETE FROM "Tour" WHERE "id" LIKE 'ej-%';
DELETE FROM "Trip" WHERE "id" LIKE 'ej-%';
DELETE FROM "City" WHERE "id" BETWEEN 900010 AND 900099;
DELETE FROM "Country" WHERE "id" BETWEEN 900001 AND 900009;
